import 'package:flutter/material.dart';

import '../l10n/app_localizations.dart';
import '../theme/brand_tokens.dart';

enum BrandLogoVariant { horizontal, primary, mark }

/// The Dalliqo logo (PNG artwork generated by tools/brand). Picks the light or dark version so the
/// wordmark keeps its contrast; [onDark] forces the dark-background artwork (e.g. on the splash).
class BrandLogo extends StatelessWidget {
  const BrandLogo({super.key, this.variant = BrandLogoVariant.horizontal, this.height = 40, this.onDark});
  final BrandLogoVariant variant;
  final double height;
  final bool? onDark;

  @override
  Widget build(BuildContext context) {
    final dark = onDark ?? Theme.of(context).brightness == Brightness.dark;
    final file = switch (variant) {
      BrandLogoVariant.mark => 'dalliqo-mark',
      BrandLogoVariant.primary => dark ? 'dalliqo-logo-primary-dark' : 'dalliqo-logo-primary',
      BrandLogoVariant.horizontal => dark ? 'dalliqo-logo-horizontal-dark' : 'dalliqo-logo-horizontal',
    };
    return Image.asset('assets/brand/$file.png', height: height, semanticLabel: '${Brand.name} — ${Brand.tagline}', filterQuality: FilterQuality.medium);
  }
}

/// Branded launch screen shown while the session is restored (matches the native splash).
class BrandSplash extends StatelessWidget {
  const BrandSplash({super.key});

  @override
  Widget build(BuildContext context) => Scaffold(
        backgroundColor: Brand.splashBackground,
        body: Center(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const BrandLogo(variant: BrandLogoVariant.primary, height: 200, onDark: true),
            const SizedBox(height: 32),
            const SizedBox(width: 28, height: 28, child: CircularProgressIndicator(strokeWidth: 2.5, color: Colors.white)),
            const SizedBox(height: 12),
            Text(context.t('app.description'), style: const TextStyle(color: Color(0xFFB8C6E0), fontSize: 13)),
          ]),
        ),
      );
}
